 move(source,world){const stroke=this.active.get(source);if(!stroke)return;const point=this.root.worldToLocal(world.clone());stroke.tip?.position.copy(point);if(point.distanceTo(stroke.points.at(-1))<.008)return;stroke.points.push(point);if(stroke.points.length>200){this.end(source);return}if(stroke.points.length<2)return;const mesh=this.makeStroke(stroke.points,stroke.color);if(stroke.mesh){stroke.mesh.geometry.dispose();stroke.mesh.material.dispose();stroke.mesh.removeFromParent()}stroke.group.add(mesh);stroke.mesh=mesh},
 loopInfo(points){if(points.length<12)return null;const box=new T.Box3().setFromPoints(points),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),axes=['x','y','z'].sort((a,b)=>size[b]-size[a]),span=Math.hypot(size[axes[0]],size[axes[1]]);if(span<.1||points[0].distanceTo(points.at(-1))>span*.38||size[axes[1]]<size[axes[0]]*.25)return null;let winding=0,length=0;for(let i=1;i<points.length;i++){const a=points[i-1].clone().sub(center),b=points[i].clone().sub(center);winding+=Math.atan2(a[axes[0]]*b[axes[1]]-a[axes[1]]*b[axes[0]],a[axes[0]]*b[axes[0]]+a[axes[1]]*b[axes[1]]);length+=points[i].distanceTo(points[i-1])}return Math.abs(winding)>4.8&&length>span*2?{center,radius:T.MathUtils.clamp(span*.34,.09,.25)}:null},
 makeJelly(info,color){const palette=['#b9dfcc','#c9bce8','#f2b9c8','#b5d6ed','#f4e3a9','#f2cab0'];color=new T.Color(palette[this.jellySerial++%palette.length]);const radius=T.MathUtils.clamp(info.radius||.12,.1,.14),friends=this.items.filter(item=>item.userData.jelly);while(friends.length>=3){const old=friends.shift();this.dispose(old);this.items=this.items.filter(item=>item!==old)}const group=new T.Group(),shell=new T.MeshBasicMaterial({color}),face=new T.MeshBasicMaterial({color:'#466b91'}),blush=new T.MeshBasicMaterial({color:'#efb4c5'}),white=new T.MeshBasicMaterial({color:'#fffdf6'}),ball=(x,y,z,r,material)=>{const mesh=new T.Mesh(new T.SphereGeometry(r,24,16),material);mesh.position.set(x,y,z);group.add(mesh);return mesh};ball(0,.025,0,1,shell).scale.set(1,.88,.78);for(let i=0;i<5;i++)ball((i-2)*.36,-.57,.12,.27,shell).scale.set(1,.75,1);for(const side of [-1,1]){ball(side*.3,.12,.72,.105,face).scale.z=.38;ball(side*.3-.026,.15,.76,.033,white);ball(side*.54,-.11,.64,.125,blush).scale.set(1,.48,.23)}const smile=new T.Mesh(new T.TorusGeometry(.15,.024,8,28,Math.PI),face);smile.rotation.z=Math.PI;smile.position.set(0,-.025,.78);group.add(smile);ball(-.35,.47,.63,.13,white).scale.set(.9,.5,.08);group.position.copy(info.center);const head=window.globiquest.xrHeadPose?.()?.position||this.el.camera.getWorldPosition(new T.Vector3());group.lookAt(this.root.worldToLocal(head.clone()));group.scale.setScalar(radius*.12);group.userData={jelly:true,baseY:group.position.y,radius,born:null,lensSubject:'jelly friend'};this.addItem(group);this.layoutJellies();this.notify('Your jelly is ready. Choose Draw another jelly to continue.');return group},
